def decompose_sum_of_squares(n: int) -> List[List[int]]:
    solutions = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            j = n // i
            if i <= j:
                e = sum_of_squares(i, j)
                f = sum_of_squares(n - i, n - j)
                solutions.append([e, f])
    return solutions
